// Optional reference round-trip. Input is a file saved by the isolated native
// reference application; it is never regenerated by this editor's writer.
const { chromium } = require('playwright');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const root = path.resolve(__dirname, '../..');
const input = process.env.SMARTART_NATIVE_RETURN;
if (!input) throw Error('Set SMARTART_NATIVE_RETURN to the reference-saved PPTX.');
const out = path.join(root, 'test-results/smartart-text-bidirectional');
fs.mkdirSync(out,{recursive:true});
const report = {scope:'Open Office -> reference desktop normal node edit -> Open Office readback',checks:[],errors:[]};
let browser;
(async()=>{try{
  const bytes = fs.readFileSync(input);
  report.inputSha256 = crypto.createHash('sha256').update(bytes).digest('hex');
  browser = await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
  const page = await browser.newPage({viewport:{width:1440,height:1000}});
  page.on('pageerror',e=>report.errors.push(e.message));
  await page.routeWebSocket('**',()=>{});
  await page.goto('http://127.0.0.1:5198/');
  await page.getByTestId('document-open-input').setInputFiles(input);
  await page.locator('[data-testid="standalone-presentation-editor"][data-ready="true"]').waitFor();
  const result = await page.evaluate(async base64=>{
    const {importPresentation}=await import('/src/presentation/core/pptx.ts');
    const model=await importPresentation(Uint8Array.from(atob(base64),x=>x.charCodeAt(0)));
    const graph=model.slides[0].objects.find(x=>x.smartArt);
    return {pages:model.slides.length,nodes:graph?.smartArt?.nodes,preview:!!graph?.diagramPreview,blockedReason:graph?.smartArt?.blockedReason};
  },bytes.toString('base64'));
  assert.equal(result.pages,1); assert.equal(result.preview,true);
  assert.equal(result.nodes.find(n=>n.id==='{DB1843D3-471D-3D4F-8D9B-C7F506BC5FEE}').text,'Native Q4');
  assert.equal(result.nodes.find(n=>n.text==='def').text,'def');
  assert.equal(result.nodes.find(n=>n.text==='ghi').text,'ghi');
  report.checks.push('Reference-saved text, untouched sibling text and node IDs import correctly with a preview');
  await page.locator('[data-testid="presentation-object"][data-kind="unknown"]').click();
  const node=page.locator('[data-testid="presentation-smartart-node"][data-node-id="{DB1843D3-471D-3D4F-8D9B-C7F506BC5FEE}"]');
  assert.match(await node.innerText(),/Native Q4/);
  assert.equal(await node.isEnabled(),true);
  await node.click();
  assert.equal(await page.getByTestId('presentation-smartart-input').inputValue(),'Native Q4');
  await page.getByTestId('presentation-smartart-cancel').click();
  await page.screenshot({path:path.join(out,'native-return-editor.png')});
  report.checks.push('Actual Vue editor shows reference-edited node and can reopen its text editor');
  assert.deepEqual(report.errors,[]);
  assert.equal(crypto.createHash('sha256').update(fs.readFileSync(input)).digest('hex'),report.inputSha256);
  report.checks.push('Reference-saved source file stays unchanged during readback');
  report.ok=true;
}catch(e){report.ok=false;report.error=e.stack;process.exitCode=1;console.error(e)}finally{await browser?.close();fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report))}})();
